import Foundationenum AdventureFactory {    static func makeGraph() -> AdventureGraph {        // Level 1        let start = AdventureNode(            id: "start",            narrative: "You wake up on an empty pirate ship. No crew. No captain. The sea is calm… for now. What do you do?",            options: [                .init(title: "Sail to Tortuga", nextNodeID: "tortuga"),                .init(title: "Sail toward the British ship on the horizon", nextNodeID: "british")            ],            isEnding: false,            isSuccess: false        )        // Level 2A (Tortuga)        let tortuga = AdventureNode(            id: "tortuga",            narrative: "Tortuga appears ahead—taverns, smugglers, and bad ideas on every corner. What's your move?",            options: [                .init(title: "Recruit crew", nextNodeID: "recruit_end"),                .init(title: "Sell ship", nextNodeID: "sell_end")            ],            isEnding: false,            isSuccess: false        )        // Level 2B (British)        let british = AdventureNode(            id: "british",            narrative: "The British ship closes in and signals you to heave to. You need a story fast.",            options: [                .init(title: "Claim to be a pirate and try to commandeer the vessel", nextNodeID: "pirate_end"),                .init(title: "Claim to be captured by pirates", nextNodeID: "captured_end")            ],            isEnding: false,            isSuccess: false        )        // Level 3 endings        let recruitEnd = AdventureNode(            id: "recruit_end",            narrative: "You recruit a crew and sail to Florida in search of Spanish Gold. You only found alligators. You die trying to become the first “Florida Man” meme.",            options: [],            isEnding: true,            isSuccess: false        )        // UPDATED: sell ship = success        let sellEnd = AdventureNode(            id: "sell_end",            narrative: "You sell the ship and have yourself smuggled back to England. You find a job, get married, and settle down.",            options: [],            isEnding: true,            isSuccess: true        )        let pirateEnd = AdventureNode(            id: "pirate_end",            narrative: "You attempt to commandeer a British Man O’ War with an 800-man crew. You fail within seconds. You really are the worst pirate ever.",            options: [],            isEnding: true,            isSuccess: false        )        let capturedEnd = AdventureNode(            id: "captured_end",            narrative: "They believe you. Unfortunately you’re involuntarily enlisted into the British Navy. Assigned to a small sloop with little defenses, you are captured on your first week by actual pirates. They leave you on a deserted island.",            options: [],            isEnding: true,            isSuccess: false        )        return AdventureGraph(nodes: [            start.id: start,            tortuga.id: tortuga,            british.id: british,            recruitEnd.id: recruitEnd,            sellEnd.id: sellEnd,            pirateEnd.id: pirateEnd,            capturedEnd.id: capturedEnd        ])    }}